// Adapted from lib/busybee/src/definition.ts at 9b459ed1:162-175,215-229.
export function declaresEvent(node, event) {
  let current = node;
  while (current) {
    if ([...current.transitions.keys()].some(descriptor => matchesEventDescriptor(event, descriptor))) return true;
    current = current.parent;
  }
  return false;
}
function matchesEventDescriptor(event, descriptor) {
  if (descriptor === event || descriptor === '*') return true;
  if (!descriptor.endsWith('.*')) return false;
  const segments = descriptor.split('.');
  const tokens = event.split('.');
  return segments.every((segment,index) => segment === '*' ? index === segments.length-1 : segment === tokens[index]);
}
